class Solution {
public:
    int numberOfGoodSubarraySplits(vector<int>& nums) {
        const int MOD = 1000000007;
        long long result = 1;
        int lastOne = -1;
        bool foundOne = false;

        for (int i = 0; i < (int)nums.size(); i++) {
            if (nums[i] == 1) {
                if (foundOne) {
                    result = (result * (i - lastOne)) % MOD;
                }
                foundOne = true;
                lastOne = i;
            }
        }

        if (!foundOne) return 0;
        return (int)result;
    }
};
